/** Exercise normal planner choice through SPARQL, with all competing execution strategies left available. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class SparseJoinAggregateAutomaticTest {

	private static final String SPARSE_PROPERTY = "rdf4j.lmdb.sparseJoinAggregate.enabled";
	private static final String NATIVE_PROPERTY = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String SPARSE_PATH = "sparseJoinAggregate";
	private static final String EX = "urn:sparse-automatic:";
	private static final int ENDPOINTS = 32;
	private static final int JOIN_KEYS = 64;
	private static final String QUERY = """
			SELECT ?a ?b (COUNT(?j) AS ?count) WHERE {
			  ?a <urn:sparse-automatic:p> ?j . ?j <urn:sparse-automatic:q> ?b
			} GROUP BY ?a ?b
			""";

	private final Map<String, String> previousProperties = new HashMap<>();

	@BeforeEach
	void useNormalNativeDefaults() {
		for (String property : List.of(SPARSE_PROPERTY, NATIVE_PROPERTY)) {
			previousProperties.put(property, System.getProperty(property));
			System.clearProperty(property);
		}
	}

	@AfterEach
	void restoreProperties() {
		for (Map.Entry<String, String> entry : previousProperties.entrySet()) {
			if (entry.getValue() == null) {
				System.clearProperty(entry.getKey());
			} else {
				System.setProperty(entry.getKey(), entry.getValue());
			}
		}
	}

	@Test
	void choosesSparseAutomaticallyForBranchingJoinWithoutOptIn(@TempDir Path directory) {
		assertNull(System.getProperty(SPARSE_PROPERTY));
		Observation actual = executeFixture(directory, true);
		assertEquals(expectedCounts(), actual.counts());
		assertTrue(hasSparsePath(actual.paths()), () -> "Expected automatic sparse execution, observed " + actual.paths());
	}

	@Test
	void explicitDisableRetainsExactAutomaticResults(@TempDir Path directory) {
		System.setProperty(SPARSE_PROPERTY, "false");
		Observation actual = executeFixture(directory, true);
		assertEquals(expectedCounts(), actual.counts());
		assertFalse(hasSparsePath(actual.paths()), () -> "Disabled sparse route executed: " + actual.paths());
	}

	@Test
	void unavailableAdjacencyFallsBackWithoutChangingResults(@TempDir Path directory) {
		Observation actual = executeFixture(directory, false);
		assertEquals(expectedCounts(), actual.counts());
		assertFalse(hasSparsePath(actual.paths()), () -> "Sparse route requires adjacency: " + actual.paths());
	}

	private static Observation executeFixture(Path directory, boolean adjacency) {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,psoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				var vf = connection.getValueFactory();
				var p = vf.createIRI(EX, "p");
				var q = vf.createIRI(EX, "q");
				connection.begin();
				for (int key = 0; key < JOIN_KEYS; key++) {
					var join = vf.createIRI(EX, "j" + key);
					for (int endpoint = 0; endpoint < ENDPOINTS; endpoint++) {
						connection.add(vf.createIRI(EX, "a" + endpoint), p, join);
						connection.add(join, q, vf.createIRI(EX, "b" + endpoint));
					}
				}
				connection.commit();
			}
			if (adjacency) {
				assertTrue(AdjacencyEngagementTestAccess.buildNow(store));
			}
			try (var connection = repository.getConnection()) {
				// Explain the first execution on a fresh store, before any query can train adaptive history.
				Set<String> paths = new LinkedHashSet<>();
				collectPaths(prepare(connection).explain(Explanation.Level.Telemetry).toGenericPlanNode(), paths);
				Map<Pair, Long> counts = new HashMap<>();
				try (var result = prepare(connection).evaluate()) {
					while (result.hasNext()) {
						var row = result.next();
						Pair pair = new Pair(row.getValue("a").stringValue(), row.getValue("b").stringValue());
						assertNull(counts.put(pair, ((Literal) row.getValue("count")).longValue()),
								"Duplicate group " + pair);
					}
				}
				return new Observation(counts, paths);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static SailTupleQuery prepare(SailRepositoryConnection connection) {
		SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(QUERY);
		query.setLmdbResultCacheRequested(false);
		return query;
	}

	private static Map<Pair, Long> expectedCounts() {
		Map<Pair, Long> expected = new HashMap<>();
		for (int left = 0; left < ENDPOINTS; left++) {
			for (int right = 0; right < ENDPOINTS; right++) {
				expected.put(new Pair(EX + "a" + left, EX + "b" + right), (long) JOIN_KEYS);
			}
		}
		return expected;
	}

	private static boolean hasSparsePath(Set<String> paths) {
		return paths.stream().anyMatch(path -> path.equals(SPARSE_PATH) || path.startsWith(SPARSE_PATH + "("));
	}

	private static void collectPaths(GenericPlanNode node, Set<String> paths) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			paths.add(path);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectPaths(child, paths);
			}
		}
	}

	private record Pair(String left, String right) {
	}

	private record Observation(Map<Pair, Long> counts, Set<String> paths) {
	}
}
